import numpy as np
from collections import deque, Counter

def solve(grid):
    if not grid or not grid[0]:
        return grid

    n = len(grid)
    m = len(grid[0])
    grid_arr = np.array(grid)
    output = np.zeros((n, m), dtype=int)
    visited = np.zeros((n, m), dtype=bool)

    for i in range(n):
        for j in range(m):
            if grid_arr[i, j] != 0 and not visited[i, j]:
                # BFS to find connected component
                queue = deque([(i, j)])
                visited[i, j] = True
                component = [(i, j)]

                while queue:
                    x, y = queue.popleft()
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m and not visited[nx, ny] and grid_arr[nx, ny] != 0:
                            visited[nx, ny] = True
                            queue.append((nx, ny))
                            component.append((nx, ny))

                # Find bounding box
                min_r = min(p[0] for p in component)
                max_r = max(p[0] for p in component)
                min_c = min(p[1] for p in component)
                max_c = max(p[1] for p in component)
                h = max_r - min_r + 1
                w = max_c - min_c + 1

                # Extract pattern
                pattern = [[grid_arr[r][c] for c in range(min_c, max_c + 1)] for r in range(min_r, max_r + 1)]

                # Determine border color (most frequent on perimeter)
                perimeter_vals = []
                for r in range(h):
                    perimeter_vals.append(pattern[r][0])
                    if w > 1:
                        perimeter_vals.append(pattern[r][w-1])
                for c in range(1, w-1):
                    perimeter_vals.append(pattern[0][c])
                    if h > 1:
                        perimeter_vals.append(pattern[h-1][c])

                border_color = Counter(perimeter_vals).most_common(1)[0][0] if perimeter_vals else pattern[0][0]

                # Calculate new dimensions
                if h % 2 == 1:
                    new_h = 2 * h - 1
                else:
                    new_h = 2 * h
                if w % 2 == 1:
                    new_w = 2 * w - 1
                else:
                    new_w = 2 * w

                scaled = [[border_color for _ in range(new_w)] for _ in range(new_h)]

                # Map original pixels to even coordinates
                for r in range(h):
                    for c in range(w):
                        nr = 2 * r
                        nc = 2 * c
                        if nr < new_h and nc < new_w:
                            scaled[nr][nc] = pattern[r][c]

                # Fill horizontal gaps (even row, odd col)
                for r in range(0, new_h, 2):
                    for c in range(1, new_w, 2):
                        left = scaled[r][c-1]
                        right = scaled[r][c+1] if c+1 < new_w else left
                        if left == right:
                            scaled[r][c] = left
                        else:
                            # Choose the one that is not border color
                            if left != border_color:
                                scaled[r][c] = left
                            else:
                                scaled[r][c] = right

                # Fill vertical gaps (odd row, even col)
                for r in range(1, new_h, 2):
                    for c in range(0, new_w, 2):
                        top = scaled[r-1][c]
                        bottom = scaled[r+1][c] if r+1 < new_h else top
                        if top == bottom:
                            scaled[r][c] = top
                        else:
                            scaled[r][c] = border_color

                # Fill diagonal gaps (odd row, odd col)
                for r in range(1, new_h, 2):
                    for c in range(1, new_w, 2):
                        scaled[r][c] = border_color

                # Calculate top-left position for placement
                new_min_r = min_r - (h // 2)
                new_min_c = min_c - (w // 2)

